using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public sealed class FullRouteVerifier:N5Runner
{
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Init(){N5Args.Start<FullRouteVerifier>("-verify-route-legacy");if(N5Args.Has("-verify-route")&&(N5Args.Value("-verify-route","")==""||N5Args.Value("-verify-route","").StartsWith("-")))N5Args.Start<FullRouteVerifier>("-verify-route");}
 protected override string Evidence=>N5Args.Value("-verify-output","Validation/N5-TG-route.txt");
 protected override IEnumerator Tests(){yield return NewGame();Check(RoomSession.Instance.CurrentRoomId=="A01","actual keyboard New Game");string[] route={"A02","A03","A04","A05","A04","A03","B01","B02","B03","B04","B03","B02","B01","B05","C01","C02","C03","C04","C06"};foreach(string next in route){string before=RoomSession.Instance.CurrentRoomId;if(before=="A03"&&next=="B01")yield return ClimbHub();var exit=Array.Find(FindObjectsByType<RoomExit>(FindObjectsSortMode.None),e=>e.destinationRoomId==next);Check(exit!=null,"route authored exit "+before+" -> "+next);Vector2 goal=exit.transform.position;double start=Time.realtimeSinceStartupAsDouble;while(RoomSession.Instance.CurrentRoomId==before){double elapsed=Time.realtimeSinceStartupAsDouble-start;if(elapsed>40)throw new Exception("natural route timeout "+before+" -> "+next+" pos="+Body.position+" goal="+goal);var keys=new List<Key>();if(goal.x-Body.position.x>.25f)keys.Add(Key.RightArrow);else if(goal.x-Body.position.x<-.25f)keys.Add(Key.LeftArrow);double cycle=elapsed%.9;if(cycle<.27||cycle>=.32&&cycle<.65)keys.Add(Key.Z);if(cycle>=.34&&cycle<.37&&Player.GetComponent<PlayerDash>().hasDash&&before=="C02"&&Body.position.y>=7.6f)keys.Add(Key.C);if(elapsed%.4<.05)keys.Add(Key.X);InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}yield return Keys();yield return Ready();Check(RoomSession.Instance.CurrentRoomId==next,"physical natural route reaches "+next);if(next=="A05")yield return Pickup(()=>FindFirstObjectByType<DashPickup>(),()=>Player.GetComponent<PlayerDash>().hasDash);if(next=="B04")yield return Pickup(()=>FindFirstObjectByType<DoubleJumpPickup>(),()=>Motor.hasDoubleJump);}
  var boss=FindFirstObjectByType<BossEncounter>();yield return WalkTo(()=>boss.Fighting,Key.RightArrow,"boss start");double deadline=Time.realtimeSinceStartupAsDouble+180,nextAttack=0,jumpUntil=0,jumpedPhase=-1;
  while(boss!=null&&boss.HP>0){if(Time.realtimeSinceStartupAsDouble>deadline||RoomSession.Instance.Respawning)throw new Exception("natural route boss fight failed");double now=Time.timeAsDouble,t=now-boss.PhaseStarted;if(jumpedPhase!=boss.PhaseStarted&&Motor.Grounded&&((boss.State==BossEncounter.Phase.MeleeTell&&t>.42)||(boss.State==BossEncounter.Phase.WaveTell&&t>.62))){jumpUntil=now+.55;jumpedPhase=boss.PhaseStarted;}var keys=new List<Key>();if(Body.position.x<15.65f)keys.Add(Key.RightArrow);else if(Body.position.x>15.85f)keys.Add(Key.LeftArrow);if(now<jumpUntil)keys.Add(Key.Z);if(now>=nextAttack){keys.Add(Key.X);nextAttack=now+.4;}InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}
  yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null,"natural Ending");Check(ProgressSave.TryLoad(out var data)&&data.endingReached,"new-game natural route saved Ending");
 }
 IEnumerator Pickup(Func<MonoBehaviour> find,Func<bool> owned){double start=Time.realtimeSinceStartupAsDouble;while(!owned()){if(Time.realtimeSinceStartupAsDouble-start>25)throw new Exception("natural pickup timeout pos="+Body.position);var item=find();if(item==null)throw new Exception("authored pickup absent");float dx=item.transform.position.x-Body.position.x;var keys=new List<Key>();if(dx>.25f)keys.Add(Key.RightArrow);else if(dx<-.25f)keys.Add(Key.LeftArrow);if((Time.realtimeSinceStartupAsDouble-start)%.9<.6)keys.Add(Key.Z);InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}yield return Keys();lines.Add("PASS natural pickup "+RoomSession.Instance.CurrentRoomId);}
 IEnumerator ClimbHub(){double deadline=Time.realtimeSinceStartupAsDouble+25;while(!(Body.position.x<8.7f&&Body.position.x>7.3f&&Body.position.y>3.7f&&Motor.Grounded)){if(Time.realtimeSinceStartupAsDouble>deadline)throw new Exception("hub Step input ascent timeout "+Body.position);var keys=new List<Key>();if(Body.position.x>8.4f)keys.Add(Key.LeftArrow);else if(Body.position.x<8)keys.Add(Key.RightArrow);if(Time.realtimeSinceStartupAsDouble%.9<.6)keys.Add(Key.Z);InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}yield return Keys();yield return Keys(Key.RightArrow,Key.Z);yield return Until(()=>Body.position.x>=11.7f&&Body.position.y>5.7f&&Motor.Grounded,"hub Step to Shelf by full jump",5);yield return Keys();yield return WalkTo(()=>Body.position.x>=15,Key.RightArrow,"approach gate on Shelf");yield return Keys(Key.RightArrow,Key.C);yield return Until(()=>Body.position.x>17.4f,"physical owned Dash through G-D",3);yield return Keys();lines.Add("PASS natural Step/Shelf/G-D hub ascent");}
}


